def feature(source,t,bars):
    if type(t) is not int or t%300:raise ValueError('M5_DECISION_GRID')
    h=(t//3600)*3600;a=interval(t,bars,h-3600,h)
    if a is None:return None
    if source=='MULTISCALE_PRICE_STATE':
        q=interval(t,bars,h-4500,h-3600)
        return None if q is None else sign(aggloc(q)-F(1,2))*sign(aggloc(a)-F(1,2))
    if source=='BROKER_NATIVE_ACTIVITY_STATE':
        total=sum(b['tick_volume'] for b in a)
        return tuple(F(b['tick_volume'],total) if total else F(0) for b in a[:11])
    if source=='REGIME_AND_STRUCTURAL_BREAK_STATE':
        prev=interval(t,bars,h-7200,h-3600)
        return None if prev is None else sum(abs(x-y) for x,y in zip(sorted(map(loc,a)),sorted(map(loc,prev))))/12
    if source=='VOLATILITY_AND_REALIZED_VARIANCE_STATE':
        if any(b['open']<=0 or b['close']<=0 for b in a):return None
        # Semantic authority is the real logarithm. Decimal is synthetic QA only,
        # not a production numeric environment or an exact real-arithmetic claim.
        with localcontext() as ctx:
            ctx.prec=80
            def dec(x):
                q=F(x);return Decimal(q.numerator)/Decimal(q.denominator)
            r=[(dec(b['close'])/dec(b['open'])).ln() for b in a];q=[x*x for x in r];total=sum(q)
            return sum((x/total)**2 for x in q) if total else Decimal(0)
    raise ValueError('NO_AUTHORIZED_EXACT_MAP')

def forecasts(fit,b,phi):
    f,coef=fit
    pb,_=predict(f,b,phi)
    xx=(np.r_[b,phi]-f.means)/f.sds;xx[f.zero]=0
    xs=[np.r_[1.,xx[:10],xx[10]],np.r_[1.,xx[:10],xx[11]],np.r_[1.,xx]]
    return pb,np.clip([x@beta for x,beta in zip(xs,coef)],-8,8)

def weights_equal_identity(ids):
    _, inv, counts=np.unique(ids,return_inverse=True,return_counts=True)
    # Total weight one, equally allocated to identities, then their events.
    return 1.0/(len(counts)*counts[inv])

def solve_ridge(x,y,w):
    z=np.column_stack([np.ones(len(x)),x])
    penalty=np.full(z.shape[1],0.5);penalty[0]=0.05
    return np.linalg.solve((z*w[:,None]).T@z+np.diag(penalty),z.T@(w*y))

def update(self,day):
  if day==self.fitted_day:return
  # causal periodic reanchor, finite trailing history; bounded overlay.
  if self.anchor is None or day-self.anchor_day>=7:
   self.anchor=self.fit_window(day,56);self.anchor_day=day
  recent=self.fit_window(day,7)
  self.state=tuple(.75*a+.25*b for a,b in zip(self.anchor,recent))
  self.fitted_day=day
  # retain at most 63 UTC maturity-day buckets; no hidden infinite state.
  self.daily={k:v for k,v in self.daily.items() if k>=day-63}

def holm_adjust(p_values: dict[str, float]) -> dict[str, float]:
    ordered = sorted(p_values.items(), key=lambda item: (item[1], item[0]))
    adjusted: dict[str, float] = {}
    running = 0.0
    count = len(ordered)
    for index, (key, p_value) in enumerate(ordered):
        running = max(running, min(1.0, p_value * (count - index)))
        adjusted[key] = running
    return adjusted

def bootstrap_max(g,bank):
    # Common bank R x B signs multiply the entire 261-leaf block vector.
    nt,B,L=g['u'].shape
    totals=(bank@g['u'].transpose(1,0,2).reshape(B,nt*L)).reshape(len(bank),nt,L).transpose(1,0,2)
    var=(g['n'][:,None,:]*g['s2'][:,None,:]-totals**2)/np.maximum(g['n'][:,None,:]-1,1)
    ts=totals/np.sqrt(np.maximum(var,1e-24));ts=np.where(g['support'][:,None,:],ts,-np.inf)
    return np.sort(ts.max(-1),axis=1)
